:root {
  --bg-card: #f0e9d6;
  --bg-header: #3b2a1a;
  --bg-bar: #d6c9a8;
  --color-high: #8b2c2c;
  --color-mid: #b8852a;
  --color-low: #4a7a5c;
  --text-primary: #2a1a0a;
  --text-secondary: #6b4f2e;
  --text-light: #f0e9d6;
  --border-color: #c2a86e;
  --accent-line: #8b2c2c;
}

article.tuning-log {
  background-color: var(--bg-card);
  border: 2px solid var(--border-color);
  border-radius: 4px;
  width: 460px;
  padding: 0;
  overflow: hidden;
}

.log-header {
  background-color: var(--bg-header);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
}

.log-label {
  color: var(--text-light);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.log-number {
  color: var(--border-color);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.puppet-name {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 10px 16px 8px;
  border-bottom: 1px solid var(--border-color);
}

.name-title {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-secondary);
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.name-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.03em;
}

.string-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 16px;
}

.string-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.string-id {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-secondary);
  width: 18px;
  letter-spacing: 0.05em;
}

.string-label {
  font-size: 12px;
  color: var(--text-primary);
  width: 110px;
  flex-shrink: 0;
}

.tension-bar {
  flex: 1;
  height: 10px;
  background-color: var(--bg-bar);
  border-radius: 2px;
  overflow: hidden;
  border: 1px solid var(--border-color);
}

.tension-fill {
  height: 100%;
  border-radius: 2px;
}

.fill-high {
  background-color: var(--color-high);
  width: 90%;
}

.fill-mid {
  background-color: var(--color-mid);
  width: 65%;
}

.fill-low {
  background-color: var(--color-low);
  width: 40%;
}

.tension-val {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary);
  width: 30px;
  text-align: right;
}

.log-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  border-top: 2px solid var(--accent-line);
  background-color: var(--bg-card);
}

.footer-note {
  font-size: 11px;
  color: var(--text-secondary);
  font-style: italic;
}

.footer-date {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.1em;
}
